INSERT INTO categories (id, name, slug, description) VALUES
('veg', 'Veg Pickles', 'veg-pickles', 'Authentic traditional Indian vegetarian pickles prepared with heirloom grandma recipes, cold-pressed oils, and ground spices.'),
('non-veg', 'Non-Veg Pickles', 'non-veg-pickles', 'Rich, spicy, slow-cooked non-vegetarian pickles featuring premium chicken, country chicken, fish, prawns, mutton, and gongura pairings.')
INSERT INTO products (id, name, slug, category_id, description, price_in_paise, package_weight_grams, image_url, is_available, is_featured, spice_level) VALUES
('prod-v-01', 'Mango Avakaya Pickle', 'mango-avakaya-pickle', 'veg', 'The king of Andhra pickles made from freshly hand-cut raw sour mangoes, fiery Guntur red chilli powder, stone-ground mustard, and cold-pressed sesame oil.', 15000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-v-02', 'Bellam Avakaya Pickle', 'bellam-avakaya-pickle', 'veg', 'A classic sweet-and-spicy delicacy crafted with raw mango pieces blended with organic country jaggery (bellam) and hand-pounded spices.', 14000, 250, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=600&auto=format&fit=crop&q=80', true, true, 'Medium'),
('prod-v-03', 'Coriander Pickle', 'coriander-pickle', 'veg', 'Fragrant fresh coriander (kotthimeera) leaves slow-tempered with tamarind, roasted cumin, and garlic in traditional wood-pressed oil.', 14000, 250, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-04', 'Red Chilli Pickle', 'red-chilli-pickle', 'veg', 'Traditional ripe red chillies (pandu mirapakaya pachadi) ground with sour tamarind and fenugreek seeds for an authentic spicy kick.', 14000, 250, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=600&auto=format&fit=crop&q=80', true, true, 'Extra Spicy'),
('prod-v-05', 'Mango Thokku Pickle', 'mango-thokku-pickle', 'veg', 'Finely grated sour green mangoes slow-simmered with mustard seeds, asafoetida, and spicy red chilli seasoning.', 14000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-06', 'Ginger Pickle', 'ginger-pickle', 'veg', 'Fresh aromatic ginger roots (allam pachadi) balanced with tangy tamarind and pure jaggery. The classic pairing for hot dosas and rice.', 14000, 250, 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=600&auto=format&fit=crop&q=80', true, true, 'Medium'),
('prod-v-07', 'Curry Leaves Pickle', 'curry-leaves-pickle', 'veg', 'Crisp hand-picked curry leaves (karivepaku pachadi) slow-roasted with red chillies, garlic cloves, and aromatic spices.', 14000, 250, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-08', 'Garlic Pickle', 'garlic-pickle', 'veg', 'Plump golden garlic cloves marinated in sour tamarind paste, fenugreek, and cold-pressed gingelly oil.', 14000, 250, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-v-09', 'Drumsticks Pickle', 'drumsticks-pickle', 'veg', 'Fresh tender drumstick pieces simmered in spicy mustard-tamarind gravy until succulent and bursting with coastal flavor.', 14000, 250, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-10', 'Green Chilli Pickle', 'green-chilli-pickle', 'veg', 'Hand-slit spicy green chillies seasoned with yellow mustard powder, roasted fenugreek, and tart lemon juice.', 14000, 250, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-v-11', 'Lemon Pickle', 'lemon-pickle', 'veg', 'Sun-matured juicy yellow lemons cured in rock salt, turmeric, and Grandma’s secret roasted spice blend.', 14000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-12', 'Tomato Pickle', 'tomato-pickle', 'veg', 'Sun-dried country tomatoes pounded with tangy tamarind, garlic slivers, and fiery red chili paste.', 14000, 250, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-13', 'Tamarind Pickle', 'tamarind-pickle', 'veg', 'Aged dark tamarind (chintakaya pachadi) seasoned with roasted cumin, fenugreek, and tempered sesame oil.', 14000, 250, 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-14', 'Bitter Gourd Pickle', 'bitter-gourd-pickle', 'veg', 'Thinly sliced bitter gourd (kakarakaya) fried to crisp perfection and soaked in a sour, spicy tamarind-mustard masala.', 14000, 250, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-15', 'Gongura Pickle', 'gongura-pickle', 'veg', 'The pride of Andhra culinary tradition! Tart sorrel leaves slow-cooked in cold-pressed oil with roasted spices and whole garlic.', 14000, 250, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-v-16', 'Amla Pickle', 'amla-pickle', 'veg', 'Whole Indian gooseberries (usirikaya) infused with tangy mustard oil, red chili, and Grandma’s rock-salt curing method.', 14000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-17', 'Cauliflower Pickle', 'cauliflower-pickle', 'veg', 'Crisp florets of cauliflower tossed in sun-warmed mustard seed paste, sour tamarind, and aromatic chili oil.', 14000, 250, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-18', 'Pudina Pickle', 'pudina-pickle', 'veg', 'Garden-fresh mint leaves slow-cooked with roasted cumin seeds, garlic cloves, and a hint of sour tamarind.', 14000, 250, 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-19', 'Nallerukada Pickle', 'nallerukada-pickle', 'veg', 'Rare herbal Cissus quadrangularis (nalleru stems) cleaned meticulously and pickled according to ancient traditional recipes.', 14000, 250, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-20', 'Dabbakaya Pickle', 'dabbakaya-pickle', 'veg', 'Traditional wild Indian citron (dabbakaya) cured in fragrant spices, fenugreek, and cold-pressed gingelly oil.', 14000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, false, 'Medium'),
('prod-v-21', 'Red Chilli Gongura Pickle', 'red-chilli-gongura-pickle', 'veg', 'A powerhouse combination of sour sorrel leaves (gongura) and fresh ripe red chillies (pandu mirapakaya) pounded together.', 14000, 250, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-v-22', 'Vankaya Pickle', 'vankaya-pickle', 'veg', 'Small tender purple brinjals stuffed and pickled in aromatic mustard-chili masala and wood-pressed oil.', 14000, 250, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80', true, false, 'Medium')
INSERT INTO products (id, name, slug, category_id, description, price_in_paise, package_weight_grams, image_url, is_available, is_featured, spice_level) VALUES
('prod-nv-01', 'Chicken Pickle', 'chicken-pickle', 'non-veg', 'Tender chicken pieces deep-fried to golden perfection and coated in rich homemade ginger-garlic and roasted red chili gravy.', 25000, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-nv-02', 'Boneless Chicken Pickle', 'boneless-chicken-pickle', 'non-veg', 'Prime cut 100% boneless chicken breast chunks cooked with stone-ground spices, pure cold-pressed oil, and fresh lemon essence.', 30000, 250, 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-nv-03', 'Natukodi Pickle', 'natukodi-pickle', 'non-veg', 'Traditional country chicken (desi fowl) known for its deep earthy flavor, slow-cooked in robust Andhra village style masala.', 35000, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, true, 'Extra Spicy'),
('prod-nv-04', 'Korameenu Pickle', 'korameenu-pickle', 'non-veg', 'Freshwater Murrel fish (Korameenu) cleaned, crisply fried, and steeped in tangy tamarind, garlic, and fenugreek masala.', 32500, 250, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-05', 'Pandugappa Fish Pickle', 'pandugappa-fish-pickle', 'non-veg', 'Delicacy Asian Sea Bass (Barramundi / Pandugappa) filleted and pickled in Grandma’s signature aromatic spice infusion.', 40000, 250, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-nv-06', 'Crab Pickle', 'crab-pickle', 'non-veg', 'Fresh coastal crab meat seasoned with crushed black pepper, fennel, roasted red chillies, and garlic cloves.', 32500, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-07', 'Small Prawn Pickle', 'small-prawn-pickle', 'non-veg', 'Tender baby prawns marinated in turmeric and deep-fried before blending into thick fiery ginger-chilli gravy.', 37500, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, true, 'Spicy'),
('prod-nv-08', 'Large Prawn Pickle', 'large-prawn-pickle', 'non-veg', 'King-sized jumbo prawns seasoned with freshly ground dry spices, cold-pressed oil, and pure lemon juice.', 42500, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-09', 'Mutton Pickle', 'mutton-pickle', 'non-veg', 'Rich succulent mutton morsels cooked tender, flash-fried, and preserved in Grandma’s signature aromatic Andhra spices.', 42500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, true, 'Extra Spicy'),
('prod-nv-10', 'Boneless Mutton Pickle', 'boneless-mutton-pickle', 'non-veg', 'Premium cut bone-free tender meat slow-cooked until meltingly tender and immersed in rich roasted garam masala.', 47500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, true, 'Extra Spicy'),
('prod-nv-11', 'Mutton Kheema Pickle', 'mutton-kheema-pickle', 'non-veg', 'Fine minced mutton slow-simmered with crushed ginger, garlic, cloves, cinnamon, and red chili oil.', 47500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-12', 'Cheruvu Fish', 'cheruvu-fish', 'non-veg', 'Fresh local lake fish (Cheruvu Chepa) cleaned and fried crisp, then preserved in spicy garlic-mustard oil.', 30000, 250, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-13', 'Metalllu Fish', 'metallu-fish', 'non-veg', 'Small silver freshwater anchovies (Nethallu/Metalllu) roasted crisp and pickled in authentic coastal tamarind masala.', 30000, 250, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-14', 'Chicken Gongura', 'chicken-gongura', 'non-veg', 'The legendary pairing of succulent bone-in chicken and tangy Andhra sorrel leaves slow-cooked in fragrant gingelly oil.', 25000, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-nv-15', 'Boneless Chicken Gongura', 'boneless-chicken-gongura', 'non-veg', 'Bite-sized boneless chicken pieces infused with tart sour gongura leaves, green chillies, and roasted spice masala.', 30000, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, true, 'Extra Spicy'),
('prod-nv-16', 'Natukodi Gongura', 'natukodi-gongura', 'non-veg', 'Earthy desi country chicken slow-roasted with wild red sorrel leaves and whole garlic cloves. Authentic village recipe.', 35000, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-nv-17', 'Small Prawn Gongura', 'small-prawn-gongura', 'non-veg', 'Juicy small prawns sautéed and cooked into sour gongura leaf paste with roasted coriander and red chillies.', 37500, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-18', 'Large Prawn Gongura', 'large-prawn-gongura', 'non-veg', 'Large plump king prawns infused with tangy gongura gravy, fried garlic slivers, and cold-pressed sesame oil.', 42500, 250, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy'),
('prod-nv-19', 'Mutton Gongura', 'mutton-gongura', 'non-veg', 'Tender bone-in mutton pieces braised in sour gongura leaf curry and pickled with aromatic whole spices.', 37500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-nv-20', 'Boneless Mutton Gongura', 'boneless-mutton-gongura', 'non-veg', 'Melt-in-mouth chunks of boneless mutton simmered in dark tangy gongura and hand-ground garam masala.', 47500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, false, 'Extra Spicy'),
('prod-nv-21', 'Mutton Kheema Gongura', 'mutton-kheema-gongura', 'non-veg', 'Finely minced mutton cooked with crushed sour gongura leaves, cumin, cloves, and ginger in a thick luscious pickle paste.', 42500, 250, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600&auto=format&fit=crop&q=80', true, false, 'Spicy')
